//! Gameplay on the islands of a V9 sky (expansion plan WP-SKY, T20; the content itself is
//! generated by [`crate::worldgen::sky::isles`]):
//!
//! * **Sky caches and nests** ([`SkyTile::Cache`], [`SkyTile::Nest`]): drilled open for
//!   credits and sky loot (skystone, cloud silver, wind astrolabes, cloud pearls) spilled as
//!   drops ([`sky_cache_loot`]). Blasts spare them (like cave caches); a collapsing isle spills
//!   their loot without the credits.
//! * **Fuel buoys** ([`crate::worldgen::sky::BuoySite`]): a rig parked on a buoy's pad buys
//!   one expensive refill per buoy ([`BUOY_PRICE`] for at most [`BUOY_FUEL`](crate::worldgen::sky::isles::BUOY_FUEL), and never past
//!   [`buoy_fill_level`](crate::worldgen::sky::isles::buoy_fill_level); [`crate::SessionServiceRequest::SkyBuoy`]). Players remember which
//!   buoys they drained (`VillageJournal::buoys`).
//! * **Sky crafting** at sky town counters ([`crate::skycraft`]).
//! * **Collapsing isles**: break a crumbling isle's [`SkyTile::Keystone`] (drill, blast,
//!   gravity bomb, gun) and the island falls apart from the underside up over a few seconds,
//!   shedding falling rock, its ore and its caches' loot; a collapsing island cracks the keystones of
//!   crumbling neighbours within [`CHAIN_RADIUS`] once it is half gone, so one well-placed
//!   gravity bomb can bring down a whole cluster.
//!
//! The collapse needs no saved state: an island whose keystone tile is gone is collapsing, and
//! what is left of it is in the terrain. It runs only near rigs (like streaming), every
//! [`COLLAPSE_STEP_MILLIS`].

use crate::{
    event::{GameplayEventKind, TickOutput},
    ids::PlayerId,
    item::{ItemKind, ItemStack},
    sky::SkyTile,
    skycraft::SkyRecipe,
    summary::PlayerScopedCommandOutcome,
    terrain::{ArtifactKind, MineralKind, TILE_SIZE, TileKind, TilePosition},
    worldgen::{
        FeatureId, TileRect,
        noise::hash2,
        sky::{
            self, BuoySite, SkyLand,
            isles::{BUOY_PRICE, buoy_of, buoy_refill},
        },
    },
};

use super::WorldState;

/// How often a collapsing island sheds its next batch of tiles.
pub const COLLAPSE_STEP_MILLIS: u64 = 120;
/// Tiles (between bounds) within which a collapsing island cracks a crumbling neighbour.
pub const CHAIN_RADIUS: i32 = 22;
/// Columns and rows around each rig whose islands are checked for collapse.
const COLLAPSE_REACH: (i32, i32) = (90, 70);
/// Most falling rocks one collapse step throws.
const ROCKS_PER_STEP: usize = 3;
/// Lifetime of a falling rock from a collapse.
const ROCK_LIFE_MILLIS: u64 = 7_000;

const SALT_SKY_CACHE: u64 = 0x5C1E_0301;
const SALT_COLLAPSE: u64 = 0x5C1E_0302;

/// What a sky cache or nest holds.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SkyLoot {
    pub credits: u32,
    pub items: Vec<ItemStack>,
}

/// The loot of the sky cache or nest `tile` at `position` (archipelago caches, above
/// [`sky::ARCHIPELAGO_BOTTOM_ROWS`], hold more).
#[must_use]
pub fn sky_cache_loot(seed: u64, position: TilePosition, tile: SkyTile) -> SkyLoot {
    let roll = hash2(seed, SALT_SKY_CACHE, position.x, position.y);
    let high = -position.y >= sky::ARCHIPELAGO_BOTTOM_ROWS;
    let part = |shift: u32, modulo: u64| u32::try_from((roll >> shift) % modulo).unwrap_or(0);
    let mut items = Vec::new();
    let credits = match tile {
        SkyTile::Cache => {
            items.push(ItemStack::new(
                ItemKind::Mineral(MineralKind::Skystone),
                3 + part(8, 4),
            ));
            let silver = if high { 2 + part(12, 4) } else { part(12, 2) };
            if silver > 0 {
                items.push(ItemStack::new(
                    ItemKind::Mineral(MineralKind::CloudSilver),
                    silver,
                ));
            }
            if (roll >> 20).is_multiple_of(4) {
                items.push(ItemStack::new(
                    ItemKind::Artifact(ArtifactKind::WindAstrolabe),
                    1,
                ));
            } else if high && (roll >> 24).is_multiple_of(6) {
                items.push(ItemStack::new(
                    ItemKind::Artifact(ArtifactKind::CloudPearl),
                    1,
                ));
            }
            let base = if high { 180 } else { 90 };
            base + part(28, u64::from(base))
        }
        SkyTile::Nest => {
            if high && (roll >> 8).is_multiple_of(3) {
                items.push(ItemStack::new(
                    ItemKind::Artifact(ArtifactKind::CloudPearl),
                    1,
                ));
            } else {
                items.push(ItemStack::new(
                    ItemKind::Mineral(MineralKind::Skystone),
                    1 + part(12, 2),
                ));
            }
            part(16, 30)
        }
        _ => 0,
    };
    SkyLoot { credits, items }
}

/// Whether `land` is a crumbling isle (it has a keystone).
fn keystone_of(land: &SkyLand) -> Option<TilePosition> {
    land.content().and_then(|content| content.keystone)
}

impl WorldState {
    /// A player drilled a sky cache or nest open: credits to them, the loot spilled as drops.
    pub(super) fn open_sky_cache(
        &mut self,
        player_id: PlayerId,
        target: TilePosition,
        tile: SkyTile,
        output: &mut TickOutput,
    ) {
        let loot = sky_cache_loot(self.terrain.seed(), target, tile);
        if let Some(player) = self.players.get_mut(&player_id) {
            player.credits = player.credits.saturating_add(loot.credits);
        }
        #[allow(clippy::cast_precision_loss, reason = "tile coordinates are small")]
        let (x, y) = (
            (target.x as f32 + 0.5) * TILE_SIZE,
            (target.y as f32 + 0.5) * TILE_SIZE,
        );
        for (index, stack) in loot.items.iter().enumerate() {
            #[allow(clippy::cast_precision_loss, reason = "a handful of stacks")]
            let spread = (index as f32 - 0.5) * 60.0;
            let _ = self.spawn_loot(x, y, (spread, -150.0), *stack, None);
        }
        output.push_event(GameplayEventKind::SkyCacheOpened {
            player_id,
            tile,
            credits: loot.credits,
        });
    }

    /// The fuel buoy `player_id`'s rig is parked on, if any (its pad intact).
    #[must_use]
    pub fn buoy_at_rig(&self, player_id: PlayerId) -> Option<BuoySite> {
        let settings = self.terrain.settings();
        if !settings.generator.has_sky_isles() {
            return None;
        }
        let rig = self.players.get(&player_id)?.tile_position(TILE_SIZE);
        if -rig.y < sky::LOW_ISLES_BOTTOM_ROWS - 8 {
            return None;
        }
        sky::lands_touching(settings, &TileRect::around(rig, 4, 4))
            .iter()
            .filter_map(buoy_of)
            .find(|buoy| {
                buoy.serves(rig)
                    && self
                        .terrain
                        .tile(buoy.pad)
                        .is_some_and(|tile| tile.kind == TileKind::Sky(SkyTile::BuoyPad))
            })
    }

    /// Whether `player_id` has already drained buoy `isle`.
    #[must_use]
    pub fn buoy_used(&self, player_id: PlayerId, isle: FeatureId) -> bool {
        self.players
            .get(&player_id)
            .is_some_and(|player| player.villages.buoys.contains(&isle))
    }

    /// Buys buoy `isle`'s one refill for `player_id`: up to [`BUOY_FUEL`](crate::worldgen::sky::isles::BUOY_FUEL) (never past
    /// [`buoy_fill_level`](crate::worldgen::sky::isles::buoy_fill_level)) for [`BUOY_PRICE`]. Refused when the rig is not on that buoy's pad,
    /// the buoy is drained for this player, the tank is too full for it or the credits fall
    /// short.
    pub(super) fn apply_buoy_refill(
        &mut self,
        player_id: PlayerId,
        isle: FeatureId,
    ) -> PlayerScopedCommandOutcome {
        if self
            .buoy_at_rig(player_id)
            .is_none_or(|buoy| buoy.isle != isle)
            || self.buoy_used(player_id, isle)
        {
            return PlayerScopedCommandOutcome::IgnoredUnavailable;
        }
        let Some(player) = self.players.get_mut(&player_id) else {
            return PlayerScopedCommandOutcome::UnknownPlayer;
        };
        let added = buoy_refill(player.fuel_capacity, player.fuel);
        if added < 1.0 || player.credits < BUOY_PRICE {
            return PlayerScopedCommandOutcome::IgnoredUnavailable;
        }
        player.credits -= BUOY_PRICE;
        player.fuel = (player.fuel + added).min(player.fuel_capacity);
        player.villages.buoys.insert(isle);
        PlayerScopedCommandOutcome::Applied
    }

    /// Crafts tier `tier` of sky recipe `recipe` for `player_id` (a sky town counter).
    pub(super) fn apply_sky_craft(
        &mut self,
        player_id: PlayerId,
        recipe: SkyRecipe,
        tier: u8,
    ) -> PlayerScopedCommandOutcome {
        let Some(player) = self.players.get_mut(&player_id) else {
            return PlayerScopedCommandOutcome::UnknownPlayer;
        };
        if crate::skycraft::craft(player, recipe, tier).is_err() {
            return PlayerScopedCommandOutcome::IgnoredUnavailable;
        }
        PlayerScopedCommandOutcome::Applied
    }

    /// Collapsing isles near rigs shed their next batch of tiles; keystones broken this tick
    /// raise [`GameplayEventKind::IsleCollapsing`]. Runs before the tick's terrain journal is
    /// taken, so its own writes replicate with the tick.
    pub(super) fn advance_sky_isles(&mut self, output: &mut TickOutput) {
        let settings = *self.terrain.settings();
        if !settings.generator.has_sky_isles() || self.players.is_empty() {
            return;
        }
        // Keystones broken this tick (by anything) announce their collapse.
        let broken: Vec<TilePosition> = self
            .terrain
            .journal()
            .iter()
            .filter(|change| {
                change.tile.kind != TileKind::Sky(SkyTile::Keystone)
                    && -change.position.y >= sky::LOW_ISLES_BOTTOM_ROWS
            })
            .map(|change| change.position)
            .collect();
        for position in broken {
            let lands = sky::lands_touching(
                &settings,
                &TileRect {
                    min: position,
                    max: position,
                },
            );
            if lands.iter().any(|land| keystone_of(land) == Some(position)) {
                output.push_event(GameplayEventKind::IsleCollapsing {
                    x: position.x,
                    y: position.y,
                });
            }
        }
        let period = self.timing.ticks_for_millis(COLLAPSE_STEP_MILLIS).max(1);
        if !self.simulation_tick.get().is_multiple_of(period) {
            return;
        }
        // Islands near any rig, in id order.
        let mut near: Vec<SkyLand> = Vec::new();
        for player in self.players.values() {
            let rig = player.tile_position(TILE_SIZE);
            if -rig.y < sky::LOW_ISLES_BOTTOM_ROWS - COLLAPSE_REACH.1 {
                continue;
            }
            near.extend(
                sky::lands_touching(
                    &settings,
                    &TileRect::around(rig, COLLAPSE_REACH.0, COLLAPSE_REACH.1),
                )
                .into_iter()
                .filter(|land| land.kind.is_island()),
            );
        }
        near.sort_by_key(|land| land.id);
        near.dedup_by_key(|land| land.id);
        for land in &near {
            let Some(keystone) = keystone_of(land) else {
                continue;
            };
            let intact = self
                .terrain
                .tile(keystone)
                .is_some_and(|tile| tile.kind == TileKind::Sky(SkyTile::Keystone));
            if !intact {
                self.collapse_step(land, &near, output);
            }
        }
    }

    /// One step of `land`'s collapse: the lowest batch of what is left of it falls away.
    fn collapse_step(&mut self, land: &SkyLand, near: &[SkyLand], output: &mut TickOutput) {
        let bounds = land.bounds();
        let mut generated = 0_usize;
        let mut left: Vec<(TilePosition, TileKind)> = Vec::new();
        for position in bounds.positions() {
            if land.tile_at(position.x, position.y).is_none() {
                continue;
            }
            generated += 1;
            if let Some(tile) = self.terrain.tile(position)
                && tile.kind != TileKind::Air
                && !matches!(tile.kind, TileKind::Built(_))
            {
                left.push((position, tile.kind));
            }
        }
        if left.is_empty() {
            return;
        }
        let seed = self.terrain.seed();
        // Lowest first, shuffled within a row.
        left.sort_by_key(|(position, _)| {
            (
                std::cmp::Reverse(position.y),
                hash2(seed, SALT_COLLAPSE, position.x, position.y),
            )
        });
        let batch = (generated / 14).max(4);
        let mut rocks = 0_usize;
        for (index, (position, kind)) in left.iter().take(batch).enumerate() {
            if !self.terrain.set_kind(*position, TileKind::Air) {
                continue;
            }
            // A cache or nest spills its loot as it falls (nobody drilled it: no credits).
            if let TileKind::Sky(tile) = kind
                && tile.is_cache()
            {
                #[allow(clippy::cast_precision_loss, reason = "tile coordinates are small")]
                let (x, y) = (
                    (position.x as f32 + 0.5) * TILE_SIZE,
                    (position.y as f32 + 0.5) * TILE_SIZE,
                );
                for stack in sky_cache_loot(seed, *position, *tile).items {
                    let _ = self.spawn_loot(x, y, (0.0, 40.0), stack, None);
                }
            }
            // Ore and finds fall with the rock (WP-DROPS); plain rock crumbles to dust.
            if matches!(
                ItemKind::from_tile(*kind),
                Some(ItemKind::Mineral(_) | ItemKind::Artifact(_))
            ) {
                let _ = self.spawn_tile_drop(*position, *kind, (0.0, 40.0));
            }
            if rocks < ROCKS_PER_STEP && index % 5 == 0 {
                #[allow(clippy::cast_precision_loss, reason = "tile coordinates are small")]
                let (x, y) = (
                    (position.x as f32 + 0.5) * TILE_SIZE,
                    (position.y as f32 + 0.5) * TILE_SIZE,
                );
                self.spawn_falling_boulder(x, y, 0, ROCK_LIFE_MILLIS);
                rocks += 1;
            }
        }
        if rocks > 0 {
            output.push_event(GameplayEventKind::BouldersChanged);
        }
        // Half gone: the shock cracks crumbling neighbours' keystones.
        if (left.len() - batch.min(left.len())) * 2 < generated {
            for other in near {
                if other.id == land.id {
                    continue;
                }
                let Some(keystone) = keystone_of(other) else {
                    continue;
                };
                if !other.bounds().expanded(CHAIN_RADIUS).intersects(&bounds) {
                    continue;
                }
                let intact = self
                    .terrain
                    .tile(keystone)
                    .is_some_and(|tile| tile.kind == TileKind::Sky(SkyTile::Keystone));
                if intact && self.terrain.set_kind(keystone, TileKind::Air) {
                    output.push_event(GameplayEventKind::IsleCollapsing {
                        x: keystone.x,
                        y: keystone.y,
                    });
                }
            }
        }
    }
}
